#include "captured_scene.hpp"
#include "mesh_lod.hpp"
#include <iostream>
#include <chrono>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("Pass package directory and original resources");Resources r(argv[2]);r.mount(fs::path(argv[1])/"capture_assets","capture_assets");auto g=load_geometry(r,"tracks/forest/forest1/geometry/track_geom.w32");auto imported=append_captured_scene(g,r);std::map<std::pair<uint64_t,size_t>,MeshLods>cache;std::array<size_t,3>triangles{},draws{};size_t reduced=0;auto start=std::chrono::steady_clock::now();for(auto&m:g.meshes){uint64_t hash=1469598103934665603ull;for(auto&v:m.vertices)for(size_t i=0;i<sizeof(Vertex);i++)hash=(hash^reinterpret_cast<const unsigned char*>(&v)[i])*1099511628211ull;auto key=std::make_pair(hash,m.indices.size());auto it=cache.find(key);if(it==cache.end())it=cache.emplace(key,build_mesh_lods(m.vertices,m.indices)).first;auto&lod=it->second;for(int l=0;l<3;l++)triangles[l]+=lod.indices[l].size()/3;reduced+=lod.indices[2].size()<lod.indices[0].size();auto level=choose_mesh_lod(lod.error,1,100,720,1.19175f,0);++draws[level];}if(!reduced)throw std::runtime_error("LOD must reduce real captured geometry");std::cout<<Json{{"import",imported},{"unique_render_buffers",cache.size()},{"triangle_counts_all_instances",triangles},{"meshes_reducible",reduced},{"draws_at_100m_720p",draws},{"generation_seconds_host",std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()},{"windows_gpu_measured",false}}.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
